    FILE *fp_in, *fp_out;
    struct Student s_in, s_new;
    int inserted = 0;
    float sum = 0;

    // 输入新学生数据
    printf("请输入新学生数据（学号 姓名 3门成绩）：\n");
    scanf("%d %s %f %f %f", &s_new.num, s_new.name, 
          &s_new.score[0], &s_new.score[1], &s_new.score[2]);
    s_new.avg = (s_new.score[0] + s_new.score[1] + s_new.score[2]) / 3.0;

    if ((fp_in = fopen("stu_sort", "rb")) == NULL) {
        printf("无法打开文件 stu_sort\n");
        exit(0);
    }
    if ((fp_out = fopen("stu_new", "wb")) == NULL) {
        printf("无法创建文件 stu_new\n");
        exit(0);
    }

    // 归并插入逻辑（假设原文件为降序）
    while (fread(&s_in, sizeof(struct Student), 1, fp_in) == 1) {
        if (!inserted && s_new.avg > s_in.avg) {
            fwrite(&s_new, sizeof(struct Student), 1, fp_out);
            inserted = 1;
        }
        fwrite(&s_in, sizeof(struct Student), 1, fp_out);
    }

    // 如果读完了还没插入（说明新学生平均分最低）
    if (!inserted) {
        fwrite(&s_new, sizeof(struct Student), 1, fp_out);
    }

    fclose(fp_in);
    fclose(fp_out);
    printf("插入完成，已保存到 stu_new\n");
    return 0;
}
