        printf("链表为空!\n");
        return head;
    }

    p1 = head;
    while (num != p1->num && p1->next != NULL) {
        p2 = p1;
        p1 = p1->next;
    }

    if (num == p1->num) {
        if (p1 == head) {
            head = p1->next;
        } else {
            p2->next = p1->next;
        }
        printf("删除:%ld\n", num);
        free(p1);
    } else {
        printf("未找到该节点:%ld\n", num);
    }
    return head;
}
