    int i, count = 0, pos;

    // 输入新学生数据
    printf("请输入新学生数据（学号 姓名 3门成绩）：\n");
    scanf("%d %s %f %f %f", &s_new.num, s_new.name, 
          &s_new.score[0], &s_new.score[1], &s_new.score[2]);
    s_new.avg = (s_new.score[0] + s_new.score[1] + s_new.score[2]) / 3.0;

    // 1. 读取所有数据到内存
    if ((fp = fopen("stu_sort", "rb")) == NULL) {
        printf("无法打开文件 stu_sort\n");
        exit(0);
    }
    while (fread(&stu[count], sizeof(struct Student), 1, fp) == 1) {
        count++;
    }
    fclose(fp);

    // 2. 在内存中插入
    // 寻找插入位置（假设降序）
    for (pos = 0; pos < count; pos++) {
        if (s_new.avg > stu[pos].avg) break;
    }
    // 移动数据
    for (i = count; i > pos; i--) {
        stu[i] = stu[i-1];
    }
    stu[pos] = s_new;
    count++;

    // 3. 将所有数据写回原文件
    if ((fp = fopen("stu_sort", "wb")) == NULL) {
        printf("无法打开文件 stu_sort\n");
        exit(0);
    }
    for (i = 0; i < count; i++) {
        fwrite(&stu[i], sizeof(struct Student), 1, fp);
    }
    fclose(fp);

    printf("更新完成。\n");
    return 0;
